"""Reviewed Czech learning companion. These notes are GRAFIT additions, not Haindl text."""
TOPICS={
1:dict(cs='Základní pojmy rozpoznávání',en='Basic PR concepts',aim='Oddělit pozorování, reprezentaci objektu a rozhodnutí klasifikátoru.',cards=[
('Od objektu k rozhodnutí','Vstupem bývá obraz, signál nebo jiný popis objektu. Příznakový vektor x je zvolená reprezentace tohoto vstupu. Klasifikátor převádí x na rozhodnutí; kvalitu celé úlohy proto neurčuje jen poslední algoritmus.'),
('Třída není totéž co shluk','Třída vyjadřuje význam přiřazený v zadání. Shluk vzniká podle podobnosti dat a zvoleného kritéria. Jeden shluk nemusí odpovídat jedné třídě a dobré geometrické oddělení nemusí znamenat užitečné rozpoznávání.'),
('Kde vzniká chyba','Snímač, předzpracování, příznaky i rozhodovací pravidlo mohou přidat chybu. Reprezentace, která zahodí rozlišující informaci, ji dalším učením sama neobnoví. Proto ověřujeme i vstupní data a způsob anotace.'),
('Co znamená zobecnění','Cílem je rozhodovat pro další vzorky z uvažované úlohy, nikoli pouze pamatovat si trénovací příklady. Oddělení trénovacích a testovacích dat musí respektovat i osoby, objekty nebo měřicí série.')],
example=('Stejný počet pixelů, jiná informace','Dva obrázky mohou mít stejný průměrný jas, ale jiný tvar. Klasifikátor s jediným příznakem „průměrný jas“ je podle tohoto příznaku nerozliší. Přidání vhodného tvarového příznaku může pomoci; není však zárukou úspěchu na nových datech.'),pitfall='Organizační pokyny, termíny a projektové odkazy v podkladu patří k sadě 2023–2024. Pro současný běh předmětu rozhoduje aktuální zadání vyučujícího.',question='Jsou významová třída a geometrický shluk vždy totéž?',answer='Ne. Třída vychází ze zadání; shluk z definice podobnosti a optimalizačního kritéria.',model='projection'),
2:dict(cs='Bayesovská teorie rozhodování',en='Bayesian decision theory',aim='Propojit věrohodnost, apriorní pravděpodobnost a cenu chyby.',cards=[
('Co je podmíněno čím','P(ω|x) je pravděpodobnost třídy po pozorování x. Hustota p(x|ω) popisuje možné hodnoty příznaků v dané třídě. Nejde o zaměnitelné veličiny; u spojitých příznaků může hustota přesáhnout jedna.'),
('Bayesovo pravidlo','P(ω|x) = p(x|ω)P(ω) / p(x). V jmenovateli je normalizace přes všechny uvažované třídy. Pro pouhé porovnání tříd lze společný kladný jmenovatel vynechat, pro číselné posteriorní pravděpodobnosti nikoli.'),
('Rozhodnutí a ztráta','Podmíněné riziko akce a je R(a|x) = Σω λ(a,ω)P(ω|x). Volíme akci s nejmenším rizikem. Maximum posteriorní pravděpodobnosti je zvláštní případ pro nulovou ztrátu správného rozhodnutí a stejnou cenu všech chyb.'),
('Co ovlivňuje práh','Vyšší apriorní četnost nebo vyšší cena přehlédnutí třídy mění rozhodnutí i při stejné věrohodnosti. Správný práh tedy závisí na zadání, nikoli pouze na tvaru dat.')],
example=('Vzácná událost a pozitivní test','Předpokládejme četnost 1 %, citlivost 90 % a falešně pozitivní míru 5 %. Pak P(událost|+) = 0,009 / (0,009 + 0,0495) ≈ 15,4 %. Jde o syntetický pravděpodobnostní příklad, nikoli údaj o skutečném testu.'),pitfall='Záměna P(ω|x) za p(x|ω) vede k ignorování apriorní četnosti. Posteriorní pravděpodobnosti navíc nemusí být dobře kalibrované, pokud je špatně odhadnut model.',question='Kdy je MAP pravidlo současně pravidlem minimálního rizika?',answer='Při nulové ztrátě správné klasifikace a stejné kladné ceně všech chybných klasifikací.',model='bayes'),
3:dict(cs='Statistické klasifikátory',en='Statistical classifiers',aim='Číst rozhodovací funkce přes předpoklady o třídních rozděleních.',cards=[
('Model nejdříve říká, čemu věříme','Parametrický klasifikátor předpokládá určitou rodinu rozdělení. Odhad jejích parametrů z dat a samotné rozhodovací pravidlo jsou dva různé kroky. Chybné předpoklady mohou převážit výhodu snadného výpočtu.'),
('Gaussovská třída','Střední hodnota určuje polohu a kovarianční matice rozptyl i vazby mezi souřadnicemi. Mahalanobisova vzdálenost bere tuto geometrii v úvahu. Inverze kovariance vyžaduje regulérní, případně vhodně regularizovanou matici.'),
('Lineární versus kvadratická hranice','Pro Gaussovské třídy se stejnou kovariancí se kvadratické členy při porovnání odečtou. Vzniká lineární hranice. Různé kovariance obecně vedou ke kvadratické hranici; nejbližší střed v eukleidovské vzdálenosti vyžaduje ještě další zjednodušení.'),
('Odhad a numerická stabilita','Malý počet příkladů ve vysoké dimenzi může dát špatně podmíněnou kovarianci. Regularizace mění odhad a musí se nastavovat bez nahlížení do testovacích dat. V praxi se často porovnávají logaritmy skóre.')],
example=('Kdy rozhoduje prostředek','Dvě jednorozměrné normální třídy se stejnou variancí a stejnými apriorními pravděpodobnostmi mají při stejné ceně chyb hranici v polovině mezi různými středy. Změna priorů nebo variancí tuto jednoduchou konstrukci obecně ruší.'),pitfall='Nezaměňujte malé skóre vzdálenosti za posteriorní pravděpodobnost. Samotná vzdálenost neobsahuje všechny normalizační a apriorní členy.',question='Zaručuje Gaussovský model vždy lineární hranici?',answer='Ne. Lineární hranice plyne ze společné kovariance; rozdílné kovariance obecně vytvářejí kvadratické hranice.',model='gaussian'),
4:dict(cs='Strojové učení',en='Machine learning',aim='Rozlišit učení parametrů, volbu modelu a nezávislé hodnocení.',cards=[
('Co se z dat učí','Učení s učitelem využívá vstupy a cílové odpovědi. Učení bez učitele hledá strukturu bez těchto třídních štítků. Rozdíl není v konkrétním programovacím jazyce, ale v dostupné informaci a cíli úlohy.'),
('Model a jeho nastavení','Parametry se odhadují v trénování, hyperparametry se vybírají validačním postupem. I výběr příznaků, normalizace a rozhodovací práh mohou být součástí učení a musejí respektovat hranici mezi tréninkem a testem.'),
('Přeučení','Složitější model může snížit trénovací chybu a přitom zhoršit chybu na nových datech. Regularizace, vhodná kapacita a dostatek reprezentativních dat pomáhají, ale neposkytují automatickou záruku přenosu do jiné domény.'),
('Učení není důkaz kvality','Nízká optimalizační ztráta sama neprokazuje dobrou klasifikaci. Výsledky závisejí na rozdělení dat, metrice, rozdělení do sad i opakování experimentu. Test použijeme až pro závěrečný odhad výkonu vybraného postupu.')],
example=('Normalizace jako únik informace','Průměr a směrodatnou odchylku pro standardizaci spočítáme pouze z trénovací části. Stejnou transformaci potom použijeme na validaci a test. Při křížové validaci se odhad transformace opakuje uvnitř každého trénovacího foldu.'),pitfall='Opakované ladění podle testovacího výsledku mění test v další validační sadu. Stejné osoby či téměř duplicitní vzorky ve více sadách mohou hodnocení výrazně zkreslit.',question='Můžeme standardizaci před křížovou validací naučit na všech vzorcích?',answer='Ne. Transformace se učí uvnitř každého trénovacího foldu a použije se na jeho validační část.',model='regularization'),
5:dict(cs='Shlukování',en='Clustering',aim='Spojit podobnost, optimalizační kritérium a interpretaci shluků.',cards=[
('Podobnost je součást zadání','Vzdálenost a škálování příznaků zásadně určují výsledek. Jednotky jedné souřadnice mohou překrýt ostatní. Standardizace není univerzální řešení; musí odpovídat významu proměnných.'),
('Co minimalizuje k-means','K-means minimalizuje součet čtverců eukleidovských vzdáleností bodů k jejich středům. Střídá přiřazení bodů a přepočet středů. Obvykle skončí v lokálním optimu; inicializace proto ovlivňuje výsledek.'),
('Hierarchie místo jednoho dělení','Hierarchické shlukování vytváří posloupnost spojování nebo dělení. Dendrogram není automaticky správný počet tříd. Tvar stromu závisí na vzdálenosti i vazebním kritériu.'),
('Jak výsledek hodnotit','Bez štítků lze zkoumat kompaktnost, oddělení a stabilitu. Tyto vlastnosti nejsou totéž jako významová správnost. Při dostupné referenční anotaci lze přidat externí hodnocení, ale nepoužívat ji skrytě pro ladění každého kroku.')],
example=('Jeden krok k-means','Pro body 0, 1, 4, 5 a počáteční středy 0 a 5 se přiřadí dvojice {0,1} a {4,5}. Nové středy jsou 0,5 a 4,5. Součet čtverců vzdáleností potom je 1. Jde o malý syntetický příklad.'),pitfall='K-means předpokládá zvolený počet shluků a upřednostňuje kompaktní shluky ve své metrice. Výsledek nepovažujte automaticky za objevené sémantické třídy.',question='Zaručuje k-means globálně nejlepší dělení?',answer='Ne. Běžný střídavý algoritmus závisí na inicializaci a může skončit v lokálním optimu.',model='kmeans'),
6:dict(cs='Výběr a extrakce příznaků',en='Feature selection and extraction',aim='Rozlišit výběr původních souřadnic a tvorbu nové reprezentace.',cards=[
('Výběr versus extrakce','Výběr zachovává podmnožinu původních příznaků. Extrakce vytváří nové souřadnice jako funkce původního vstupu. Obě cesty mohou snížit dimenzi, ale mají odlišnou interpretaci a cenu výpočtu.'),
('PCA maximalizuje rozptyl','PCA pracuje s centrovanými daty a hledá ortogonální směry největšího rozptylu. V eukleidovské míře současně minimalizuje chybu lineární rekonstrukce dané dimenze. Největší rozptyl však nemusí být největší třídní rozlišitelnost.'),
('Škálování mění odpověď','Kovarianční PCA závisí na jednotkách vstupů. Změna jednotek jedné proměnné může změnit hlavní směr. Volba standardizace je věc zadání a odhadu na trénovacích datech.'),
('Vyhledávání podmnožin','Vyčerpávající hledání roste s počtem příznaků exponenciálně. Postupné strategie jsou levnější, ale mohou minout kombinaci příznaků, které jsou užitečné společně. Celý výběr musí být uvnitř validačního postupu.')],
example=('Rozptyl není třída','Představte si dvě třídy oddělené malým posunem ve svislém směru, ale s velkým společným vodorovným rozptylem. PCA na jednu dimenzi může zvolit vodorovný směr a třídní informaci zahodit.'),pitfall='PCA není metoda s učitelem a nevidí štítky tříd. Vysoké procento zachovaného rozptylu samo neříká, kolik klasifikační informace zůstalo.',question='Je hlavní komponenta vždy nejlepší příznak pro klasifikaci?',answer='Ne. Maximalizuje rozptyl bez znalosti štítků, nikoli obecně separaci tříd.',model='pca'),
7:dict(cs='Hodnocení klasifikace',en='Classification performance assessment',aim='Vybrat metriku podle typu chyby a správně oddělit hodnocení.',cards=[
('Nejdříve určete pozitivní třídu','TP a FN se vztahují ke skutečně pozitivním případům; FP a TN ke skutečně negativním. Bez určení pozitivní třídy a orientace matice záměn je snadné zaměnit citlivost, přesnost a specificitu.'),
('Čtyři čísla, několik otázek','Precision = TP/(TP+FP), recall = TP/(TP+FN), specificity = TN/(TN+FP). Accuracy počítá podíl všech správných rozhodnutí. Při nulovém jmenovateli je poměr nedefinovaný; dohodnuté náhradní konvence je nutné uvést.'),
('Práh mění kompromis','ROC zobrazuje TPR proti FPR, křivka precision–recall zachycuje jiný pohled. Jediné číslo AUC nenahrazuje volbu provozního bodu ani cenu chyb. Precision se mění i s apriorní četností pozitivní třídy.'),
('Nejistota odhadu','Výkon z konečného vzorku je odhad. Způsob dělení, závislosti mezi vzorky a interval nejistoty jsou součástí jeho interpretace. Téměř stejné skóre nemusí znamenat prokázaný rozdíl metod.')],
example=('Accuracy umí skrýt neúspěch','Při 990 negativních a 10 pozitivních případech má klasifikátor „vždy negativní“ accuracy 99 %, ale recall pozitivní třídy 0 %. Precision je nedefinovaná, protože nebyl předpovězen žádný pozitivní případ.'),pitfall='Nezaměňujte precision za recall ani jeden údaj bez rozmyslu nepřekládejte jako „přesnost“. Uvádějte vzorec, pozitivní třídu a jmenovatel.',question='Jaký recall má pravidlo „vždy negativní“, pokud jsou v testu pozitivní případy?',answer='Nulový: TP = 0 a FN > 0. Precision je bez předpovězených pozitivních případů nedefinovaná.',model='metrics'),
8:dict(cs='Strukturální a syntaktické rozpoznávání',en='Structural and syntactic PR',aim='Popsat objekt pomocí částí, jejich vztahů a pravidel skládání.',cards=[
('Proč nestačí vektor','U některých úloh je důležité uspořádání částí: pořadí znaků, sousednost segmentů nebo vazby v grafu. Strukturální reprezentace toto uspořádání zapisuje přímo, místo aby je vždy převáděla do pevného seznamu čísel.'),
('Primitiva a relace','Primitiva jsou základní rozpoznané části, relace popisují jejich vztahy. Volba primitiv a jejich spolehlivá detekce je klíčová. Chyba segmentace může způsobit, že správný objekt do zvolené struktury vůbec nezapadne.'),
('Gramatika a rozbor','Gramatika určuje, jak lze z terminálních symbolů pravidly vytvořit přípustný objekt. Parser zkoumá, zda a jak lze vstup odvodit. Síla gramatiky ovlivňuje vyjadřovací schopnost i složitost rozboru.'),
('Nejisté pozorování','Reálné symboly či relace bývají chybné nebo neúplné. Pravděpodobnostní modely, nákladové opravy nebo tolerantní párování dovolují nejistotu vyjádřit. Samotná existence odvození ještě neznamená nejpravděpodobnější význam.')],
example=('Jazyk aⁿbⁿ','Gramatika S → aSb | ab vytváří řetězce aⁿbⁿ pro n ≥ 1. Například aabb odvodíme S ⇒ aSb ⇒ aabb. Řetězec abab do tohoto jazyka nepatří. Je to ilustrace gramatiky, nikoli plný model obrazu.'),pitfall='Syntaktická přijatelnost a významová správnost jsou různé vlastnosti. Ukázkový rozpoznávač řetězců níže není obecný parser všech gramatik.',question='Patří abab do jazyka vytvořeného pravidly S → aSb | ab?',answer='Ne. Všechny symboly a musejí předcházet všem symbolům b a jejich počty musejí být stejné a kladné.',model='grammar'),
9:dict(cs='Neuronové sítě',en='Neural networks',aim='Propojit neuron, nelinearitu, architekturu a učení vah.',cards=[
('Neuron je funkce','Základní jednotka nejprve počítá z = wᵀx + b a poté aktivaci y = φ(z). Váhy a bias jsou parametry. Biologická inspirace není tvrzení, že tento model věrně simuluje biologický neuron.'),
('Proč nelinearita','Složení čistě lineárních a afinních vrstev je opět afinní transformace. Nelineární aktivace umožňují bohatší rozhodovací funkce. Zvolená aktivace ovlivňuje i průchod gradientu.'),
('Gradient není rozhodnutí','Zpětné šíření efektivně počítá derivace složené funkce. Optimalizátor je používá k úpravě parametrů. Ztráta a rychlost učení určují optimalizační úlohu; ani dlouhé trénování samo nezaručí dobré zobecnění.'),
('Architektura přináší předpoklady','Konvoluce využívá sdílení vah a lokální strukturu, rekurence návaznost kroků. Různé architektury odpovídají různým předpokladům. Počet parametrů není sám o sobě důkazem kvality.')],
example=('Jediný sigmoidální neuron','Pro x = 2, w = 1 a b = −1 je z = 1 a σ(z) = 1/(1+e⁻¹) ≈ 0,731. Toto číslo lze chápat jako pravděpodobnost jen při odpovídajícím modelu a výcviku; samotná sigmoidální funkce kalibraci nezaručuje.'),pitfall='Hodnota aktivace není automaticky spolehlivá pravděpodobnost. Hodnocení vyžaduje nezávislá data, vhodnou ztrátu a případně kontrolu kalibrace.',question='Získáme nelineární hranici pouhým skládáním afinních vrstev bez nelinearity?',answer='Ne. Složením afinních transformací dostaneme opět afinní transformaci.',model='neuron'),
11:dict(cs='Genetické algoritmy',en='Genetic algorithms',aim='Rozlišit reprezentaci řešení, fitness a stochastické operátory.',cards=[
('Co je jedinec','Chromozom kóduje kandidátní řešení. Fitness vyjadřuje jeho kvalitu podle konkrétního zadání. Kódování musí umožnit smysluplné vyhodnocení a buď zachovávat přípustnost, nebo mít pravidla oprav či penalizací.'),
('Selekce, křížení, mutace','Selekce preferuje určité rodiče. Křížení kombinuje jejich informace, mutace zavádí další změny. Jejich účinek závisí na reprezentaci; výměna bitů není univerzálně smysluplná pro libovolnou úlohu.'),
('Prozkoumávání a využívání','Silný selekční tlak může rychle zlepšit fitness a současně ztratit rozmanitost. Slabý tlak či velmi silné mutace mohou postup zpomalit. Elitismus uchová nejlepší jedince, ale sám neřeší předčasnou konvergenci.'),
('Jak vykazovat výsledek','Jde o stochastickou heuristiku. Uvádíme rozpočet vyhodnocení, opakování, náhodná semena a variabilitu výsledků. Nejlepší nalezené řešení není bez dalšího důkaz globálního optima.')],
example=('OneMax a mutace','V hračkové úloze maximalizujeme počet jedniček. Řetězec 10110 má fitness 3. Převrácení druhého bitu dává 11110 s fitness 4, převrácení prvního bitu však 00110 s fitness 2. Mutace tedy nemusí zlepšovat.'),pitfall='Neprezentujte jeden úspěšný běh jako záruku. Ukázka bitového operátoru níže není implementace celého genetického algoritmu.',question='Zlepšuje každá mutace fitness?',answer='Ne. Může ji zvýšit, snížit nebo ponechat stejnou; záleží na řešení, operátoru a cílové funkci.',model='mutation'),
12:dict(cs='Support Vector Machines',en='Support vector machines',aim='Číst margin, měřítko rozhodovací funkce a roli jádra.',cards=[
('Rozhodovací funkce','Lineární SVM používá znaménko wᵀx + b. Pro nenulové w je geometrická vzdálenost bodu od hranice |wᵀx+b|/‖w‖. Samotné skóre se při přenásobení w a b mění, geometrická hranice však zůstává.'),
('Kanonické měřítko a margin','V separovatelném případě se parametry škálují tak, aby yᵢ(wᵀxᵢ+b) ≥ 1. Vzdálenost mezi podpůrnými hyperrovinami wᵀx+b = ±1 je 2/‖w‖. Maximalizace tohoto marginu odpovídá minimalizaci ½‖w‖².'),
('Měkký margin','Soft-margin SVM připouští porušení pomocí slack proměnných a penalizace. Parametr C řídí kompromis mezi velikostí vah a penalizací těchto porušení. Jeho význam závisí i na škálování příznaků a použité formulaci cíle.'),
('Jádro není libovolná podobnost','Jádrový trik nahrazuje skalární součiny vhodnou jádrovou funkcí. Pro standardní konvexní SVM má být jádro pozitivně semidefinitní. Hyperparametry jádra i C se volí validačně, nikoli na testu.')],
example=('Vzdálenost od přímky','Pro w = (3,4), b = −5 a x = (1,1) je skóre 2 a ‖w‖ = 5, tedy vzdálenost od hranice 0,4. Kanonické hyperroviny se skóre ±1 mají šířku pásu 2/5 = 0,4; to je jiná veličina než vzdálenost libovolného bodu.'),pitfall='Nepovažujte 2/‖w‖ za empirický margin bez ověření kanonického měřítka a podmínek vzorků. Hračková geometrická ukázka níže SVM netrénuje.',question='Změní se geometrická hranice při násobení w i b stejným kladným číslem?',answer='Ne. Znaménko skóre i množina bodů s nulovým skóre zůstávají stejné; samotné číselné skóre se přenásobí.',model='margin')}
